const statuses={ativo:'Ativo',ganho:'Ganho',perdido:'Perdido',pendente:'Pendente',concluida:'Concluída',cancelada:'Cancelada',rascunho:'Rascunho',enviado:'Enviado',visualizado:'Visualizado',aprovado:'Aprovado',recusado:'Recusado',aberto:'Aberto',processando:'Processando',entregue:'Entregue',cancelado:'Cancelado'};
