const statusOptions=keys=>keys.map(k=>[k,statuses[k]]);
const nav=[['pipelines','▥','Pipelines','Negócios organizados do seu jeito.'],['leads','◇','Leads','Qualifique seus contatos antes da negociação.'],['aftersale','↻','Pós-venda','Acompanhe relacionamento, entrega e renovação.'],['contacts','♧','Contatos','Organizações e pessoas em uma base integrada.'],['activities','☷','Atividades','Planeje o próximo contato e acompanhe os prazos.'],['calendar','▦','Calendário','Sua agenda comercial por mês.'],['products','□','Produtos','Catálogo, preços e parâmetros comerciais.'],['quotes','≡','Orçamentos','Prepare propostas e acompanhe sua aprovação.'],['orders','▣','Pedidos','Acompanhe pedidos gerados por orçamentos aprovados.'],['documents','▤','Documentos','Modelos de propostas e impressão em PDF.'],['reports','◴','Visão geral','Indicadores calculados a partir dos seus registros.'],['settings','⚙','Configurações','Pipelines, cadastros auxiliares e proteção dos dados.']];
const cloudConfigured=!!(connection.supabaseUrl||connection.publishableKey);
let access=null,connectionError='',cloudReady=false,cloudInitialized=false,cloudBusy=false,failedCloudDraft=null,cloudMemory=null;
try{access=await connectInternal(connection);}catch(error){connectionError=error.message;}
let state,locked=false,loadError='',timer,route='pipelines',query='',pageNumber=1,view='board',contactType='organization',filters={},showFilters=false,selected=new Set(),currentRows=[],calendarMonth=today().slice(0,7),pipelineId='',pipelineDraft,quoteDraft,dialogContext;
try{state=cloudConfigured?emptyState():loadState(localStorage);}catch(e){state=emptyState();locked=true;loadError=`Não foi possível abrir os dados: ${e.message} O armazenamento original foi preservado. Exporte-o antes de restaurar um backup.`;}
pipelineId=state.pipelines[0].id;
const accounts=createAccountsUI({$,esc,button,field,formDialog,openDialog,closeDialog,notify,table,access,render,loadCloud,isSaving:()=>cloudBusy,isReady:()=>cloudReady,setReady:value=>cloudReady=value,resetPage:()=>{pageNumber=1;},clearCloud:()=>{cloudReady=false;cloudInitialized=false;state=emptyState();cloudMemory=null;selected.clear();failedCloudDraft=null;}});
const operations=createOperationsUI({$,esc,button,field,options,table,formDialog,openDialog,closeDialog,change,notify,money,date,download,uid,today,toolbar,getState:()=>state,getQuery:()=>query,setRows:rows=>{currentRows=rows;},render,resetPage:()=>{pageNumber=1;},isLocked:()=>locked||cloudConfigured&&(!cloudReady||!cloudInitialized||cloudBusy)});
