nav.sort((a,b)=>moduleOrder.indexOf(a[0])-moduleOrder.indexOf(b[0]));
nav.find(item=>item[0]==='reports')[2]='Relatórios';
nav.find(item=>item[0]==='reports')[3]='Consultas, agrupamentos e relatórios salvos.';
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,5000);}
function change(fn,message='Alterações salvas.'){if(cloudConfigured&&(!cloudReady||!cloudInitialized||cloudBusy)){notify(cloudBusy?'Aguarde a gravação terminar.':'Entre e inicialize a base antes de continuar.');return false;}if(locked){notify('Atualize a base ou restaure um backup válido antes de continuar.');return false;}try{const previous=state;const storage=access?{getItem:()=>cloudMemory,setItem:(_key,value)=>cloudMemory=value}:localStorage;const result=commit(storage,state,fn);state=result.state;if(access)persistCloud(previous,state,message);render();if(message&&!access)notify(message);return result.result??true;}catch(e){const error=$('#formError');if(error)error.textContent=e.message;else notify(e.message);return false;}}
async function loadCloud(){const result=await access.call('loadState');cloudInitialized=!!result.payload;state=result.payload||emptyState();validateState(state);cloudMemory=JSON.stringify(state);pipelineId=state.pipelines[0].id;locked=false;loadError='';selected.clear();}
async function persistCloud(previous,next,message){cloudBusy=true;accounts.header();try{const result=await access.call('saveState',{state:next,expected:previous.revision});state=result.state;cloudMemory=JSON.stringify(state);failedCloudDraft=null;if(message)notify(message);}catch(error){failedCloudDraft=structuredClone(next);state=previous;cloudMemory=JSON.stringify(previous);locked=true;loadError=`Alteração não confirmada no servidor: ${error.message} Exporte a tentativa e atualize a base antes de refazer a alteração.`;notify('Não foi possível salvar. A última base confirmada foi preservada.');}finally{cloudBusy=false;render();}}
function renderCloudInitialization(){const admin=access.profile.role==='admin';$('#pageActions').innerHTML='';$('#content').innerHTML=`<section class="panel accountsetup"><h2>A base da equipe ainda está vazia</h2><p>${admin?'Escolha como iniciar a base compartilhada. Os dados antigos deste navegador serão preservados.':'O administrador precisa inicializar a base antes de liberar o trabalho da equipe.'}</p>${admin?`<div class="actions">${button('Começar com base vazia','accountInitEmpty','','primary')}${button('Importar dados deste navegador','accountInitLocal')}</div>`:''}</section>`;}
function initializeCloud(useLocal){if(access?.profile?.role!=='admin')return;const initial=useLocal?loadState(localStorage):emptyState();formDialog('Inicializar base da equipe',`<p>${useLocal?`Serão compartilhados ${initial.deals.length} negócios e ${initial.contacts.length} contatos deste navegador.`:'Será criada uma base vazia com os pipelines padrão.'}</p>${field('confirmed','Confirmo a inicialização da base compartilhada',false,{type:'checkbox',required:true})}`,async()=>{const submit=$('#recordForm button[type=submit]');submit.disabled=true;try{await access.call('initState',{state:initial,expected:0});await loadCloud();closeDialog();render();notify('Base compartilhada inicializada.');}catch(error){$('#formError').textContent=error.message;submit.disabled=false;}});}
function button(label,action,id='',cls=''){return `<button type="button" data-action="${esc(action)}" data-id="${esc(id)}" class="${cls}">${esc(label)}</button>`;}
function options(items,value,empty){return `${empty!==undefined?`<option value="">${esc(empty)}</option>`:''}${items.map(item=>{const [id,name]=Array.isArray(item)?item:[item,item];return `<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(name)}</option>`;}).join('')}`;}
function field(name,label,value='',config={}){const attrs=`name="${esc(name)}" id="field-${esc(name)}" ${config.required?'required':''} ${config.readonly?'readonly':''} ${name==='tags'?'list="tagSuggestions"':''}`;const control=config.options?`<select ${attrs}>${options(config.options,value,config.empty)}</select>`:config.type==='textarea'?`<textarea ${attrs} rows="${config.rows||3}" maxlength="30000">${esc(value)}</textarea>`:config.type==='checkbox'?`<input ${attrs} type="checkbox" ${value?'checked':''}>`:`<input ${attrs} type="${config.type||'text'}" value="${esc(value)}" ${config.type==='number'?`min="${config.min??0}" max="${config.max??1000000000000}" step="${config.step??'0.01'}"`:''} ${config.type==='text'||!config.type?'maxlength="200"':''} ${config.placeholder?`placeholder="${esc(config.placeholder)}"`:''}>`;return `<label class="${config.wide?'widefield ':''}${config.type==='checkbox'?'checklabel':''}" for="field-${esc(name)}">${config.type==='checkbox'?control:''}${esc(label)}${config.required?' *':''}${config.type!=='checkbox'?control:''}${config.hint?`<span class="hint">${esc(config.hint)}</span>`:''}</label>`;}
function contactName(id){return state.contacts.find(c=>c.id===id)?.name||'—';}
function dealName(id){return state.deals.find(d=>d.id===id)?.title||'—';}
function pipeline(d){return state.pipelines.find(p=>p.id===d.pipelineId);}
function stageName(d){return pipeline(d)?.stages.find(s=>s.id===d.stageId)?.name||'—';}
function contactOptions(type){return state.contacts.filter(c=>(!type||c.type===type)).map(c=>[c.id,c.name+(c.active===false?' (inativo)':'')]);}
function dealOptions(){return state.deals.map(d=>[d.id,d.title]);}
function badge(value){return `<span class="badge ${value==='ganho'||value==='aprovado'||value==='entregue'?'won':value==='perdido'||value==='cancelado'||value==='recusado'?'lost':'neutral'}">${esc(statuses[value]||value)}</span>`;}
function empty(message,action,label){return `<div class="empty"><div class="emptyicon" aria-hidden="true">◇</div><p>${esc(message)}</p>${action?button(label,action,'','primary'):''}</div>`;}
function toolbar(extra='',search=true){return `<div class="toolbar"><div class="actions">${extra}</div><div class="actions">${search?`<label class="sr" for="search">Buscar registros</label><input class="search" id="search" type="search" value="${esc(query)}" placeholder="Buscar registros…">`:''}${button('↓ CSV','exportCsv')}</div></div>`;}
function table(headers,rows,emptyText='Nenhum registro encontrado.'){const pages=Math.max(1,Math.ceil(rows.length/25));pageNumber=Math.min(pageNumber,pages);return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.slice((pageNumber-1)*25,pageNumber*25).map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${headers.length}">${esc(emptyText)}</td></tr>`}</tbody></table><div class="pagination"><span>${rows.length} registros · Página ${pageNumber} de ${pages}</span><div class="actions"><button data-action="prevPage" ${pageNumber<=1?'disabled':''}>Anterior</button><button data-action="nextPage" ${pageNumber>=pages?'disabled':''}>Próxima</button></div></div></div>`;}
function openDialog(title,body,wide=false){if($('#editor').open)$('#editor').close();$('#dialogTitle').textContent=title;$('#dialogContent').innerHTML=body;$('#editor').classList.toggle('wide',wide);$('#editor').showModal();$('#editor').scrollTop=0;}
function formDialog(title,body,onSave,extra='',wide=false){openDialog(title,`<form id="recordForm"><div class="formbody">${body}<p id="formError" class="error" role="alert"></p></div><div class="dialogfoot"><button type="submit" class="primary">Salvar</button>${button('Cancelar','closeDialog')}${extra}</div></form>`,wide);$('#recordForm').onsubmit=e=>{e.preventDefault();$('#formError').textContent='';try{onSave(Object.fromEntries(new FormData(e.target)),e.target);}catch(error){$('#formError').textContent=error.message;}};}
function closeDialog(){$('#editor').close();dialogContext=null;}
function entityDeleteButton(collection,id){return id?button('Excluir registro','deleteEntity',`${collection}:${id}`,'danger'):'';}
function parseTags(v){return [...new Set(String(v||'').split(',').map(v=>v.trim()).filter(Boolean))];}
function formSearchRows(rows){return rows.filter(r=>!query||matches(JSON.stringify(r),query));}
function render(){
  accounts.header();if(cloudConfigured&&!access){$('#pageTitle').textContent='Configurar acesso';$('#pageActions').innerHTML='';accounts.render();$('#content').insertAdjacentHTML('afterbegin',`<p class="error" role="alert">${esc(connectionError)}</p>`);return;}if(access&&(!cloudReady||access.profile?.must_change_password)){accounts.renderGate();return;}
  const meta=nav.find(n=>n[0]===route)||nav[0];$('#navigation').innerHTML=nav.map(n=>`<a href="#${n[0]}" ${n[0]===route?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${n[1]}</span>${n[2]}</a>`).join('');$('#breadcrumb').textContent=`Poliniza CRM / ${meta[2]}`;$('#pageTitle').textContent=meta[2];$('#pageDescription').textContent=meta[3];document.title=`${meta[2]} · Poliniza CRM`;$('#alert').hidden=!locked;$('#alert').textContent=loadError;$('#pageActions').innerHTML='';
  if(access){$('#pageActions').insertAdjacentHTML('beforeend',button('Atualizar base','accountReloadCloud'));if(failedCloudDraft)$('#pageActions').insertAdjacentHTML('beforeend',button('Exportar tentativa não salva','accountExportDraft'));}
  if(access&&!cloudInitialized&&route!=='users'){renderCloudInitialization();return;}
  const views={users:accounts.render,pipelines:renderDeals,leads:renderDeals,aftersale:renderDeals,contacts:renderContacts,activities:renderActivities,calendar:renderCalendar,products:renderProducts,quotes:renderQuotes,orders:renderOrders,documents:renderDocuments,reports:renderReports,settings:renderSettings,...operations.views};(views[route]||renderDeals)();$('#content').insertAdjacentHTML('beforeend',`<datalist id="tagSuggestions">${state.settings.tags.map(t=>`<option value="${esc(t)}"></option>`).join('')}</datalist>`);if(['contacts','products'].includes(route))$('#pageActions').insertAdjacentHTML('afterbegin',button('Importar CSV','csvImport'));
  if(failedCloudDraft)$('#pageActions').insertAdjacentHTML('beforeend',button('Exportar tentativa não salva','accountExportDraft'));

}
function filteredDeals(){const type=route==='leads'?'lead':route==='aftersale'?'aftersale':null;let p=state.pipelines.find(p=>p.id===pipelineId&&(!type||p.type===type));if(!p)p=state.pipelines.find(p=>!type||p.type===type);if(!p)return [];pipelineId=p.id;
  return state.deals.filter(d=>d.pipelineId===p.id&&(!filters.status||filters.status==='todos'||d.status===filters.status)&&(!query||matches([d.title,contactName(d.organizationId),contactName(d.personId),d.owner,...d.tags].join(' '),query))&&(!filters.owner||matches(d.owner,filters.owner))&&(!filters.origin||d.origin===filters.origin)&&(!filters.tag||d.tags.some(t=>matches(t,filters.tag)))&&(!filters.temperature||d.temperature===filters.temperature)&&(!filters.from||d.created.slice(0,10)>=filters.from)&&(!filters.to||d.created.slice(0,10)<=filters.to));}
function renderDeals(){const shown=filteredDeals(),p=state.pipelines.find(p=>p.id===pipelineId),type=route==='leads'?'lead':route==='aftersale'?'aftersale':null;currentRows=shown;$('#pageActions').innerHTML=button('Gerenciar pipelines','managePipelines')+button('＋ Negócio','newDeal','','primary');if(!p||type&&p.type!==type){$('#content').innerHTML=empty('Crie um pipeline para organizar esta área.','newPipeline','Criar pipeline');return;}
  const pipelineSelect=`<label class="sr" for="pipelineSelect">Pipeline atual</label><select id="pipelineSelect">${options(state.pipelines.filter(p=>!type||p.type===type).map(p=>[p.id,`${p.name} · ${typeNames[p.type]}`]),p.id)}</select><label class="sr" for="dealStatus">Status</label><select id="dealStatus">${options([['ativo','Ativos'],['ganho','Ganhos'],['perdido','Perdidos'],['todos','Todos']],filters.status||'ativo')}</select>${button('Filtros','toggleFilters')}${button('⚙ Etapas','editPipeline',p.id)}`;
  const bulk=selected.size?`<div class="bulk"><strong>${selected.size} selecionados</strong>${button('Alterar em lote','bulkDeals')}${button('Limpar seleção','clearSelection')}</div>`:'';
  const controls=`${toolbar(pipelineSelect+`<div class="viewgroup">${button('Quadro','boardView','',view==='board'?'selected':'')}${button('Lista','listView','',view==='list'?'selected':'')}</div>`)}${showFilters?`<form id="filterForm" class="filters">${field('owner','Responsável',filters.owner)}${field('origin','Origem',filters.origin,{options:state.settings.origins,empty:'Todas'})}${field('tag','Tag',filters.tag)}${field('temperature','Temperatura',filters.temperature,{options:['Sem temperatura','Frio','Morno','Quente','Muito quente'],empty:'Todas'})}${field('from','Criado de',filters.from,{type:'date'})}${field('to','Criado até',filters.to,{type:'date'})}<button class="primary">Aplicar</button>${button('Limpar','clearFilters')}</form>`:''}${bulk}`;
  const card=d=>{const next=state.activities.filter(a=>a.dealId===d.id&&a.status==='pendente').sort((a,b)=>a.due.localeCompare(b.due))[0];return `<article class="deal" draggable="true" data-drag="${d.id}"><div class="cardtop"><input type="checkbox" data-select="${d.id}" aria-label="Selecionar ${esc(d.title)}" ${selected.has(d.id)?'checked':''}><button class="linkbutton cardtitle" data-action="dealDetail" data-id="${d.id}">${esc(d.title)}</button></div><p class="company">${esc(contactName(d.organizationId||d.personId))}</p><div class="cardmeta"><strong class="money">${money(d.value)}</strong><span>${esc(d.owner)}</span></div><div class="tags">${badge(d.status)}${d.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><label class="sr" for="move-${d.id}">Mover ${esc(d.title)} para etapa</label><select class="move" id="move-${d.id}" data-move="${d.id}">${options(p.stages.map(s=>[s.id,s.name]),d.stageId)}</select>${next?`<div class="nextactivity">${esc(next.title)} · ${date(next.due)}</div>`:''}${d.closing?`<div class="nextactivity">Previsão: ${date(d.closing)}</div>`:''}</article>`;};
  let body;if(view==='board')body=`<section class="board" aria-label="Quadro de negócios">${p.stages.map(st=>{const list=shown.filter(d=>d.stageId===st.id);return `<section class="column" data-stage="${st.id}" aria-label="${esc(st.name)}"><div class="stagehead"><div><h2>${esc(st.name)}</h2>${button('＋','addAtStage',st.id,'iconbutton')}</div><p>${list.length} negócios · ${st.probability}% de probabilidade</p><div class="total"><span>Total</span><strong>${money(list.reduce((s,d)=>s+d.value,0))}</strong></div></div><div class="cards">${list.map(card).join('')||empty('Nenhum negócio nesta etapa.','addAtStage','Adicionar negócio').replace('data-id=""',`data-id="${st.id}"`)}</div></section>`;}).join('')}</section>`;
  else body=table(['Seleção','Negócio','Contato','Etapa','Responsável','Valor','Status'],shown.map(d=>[`<input type="checkbox" data-select="${d.id}" aria-label="Selecionar ${esc(d.title)}" ${selected.has(d.id)?'checked':''}>`,button(d.title,'dealDetail',d.id,'linkbutton'),esc(contactName(d.organizationId||d.personId)),esc(stageName(d)),esc(d.owner),money(d.value),badge(d.status)]));
  const active=shown.filter(d=>d.status==='ativo'),weighted=active.reduce((sum,d)=>sum+d.value*(p.stages.find(s=>s.id===d.stageId)?.probability||0)/100,0);$('#content').innerHTML=controls+body+`<div class="summarybar"><span>${shown.length} negócios exibidos</span><span>Valor ativo <strong>${money(active.reduce((s,d)=>s+d.value,0))}</strong></span><span>Previsão ponderada <strong>${money(weighted)}</strong></span></div>`;
  if($('#filterForm'))$('#filterForm').onsubmit=e=>{e.preventDefault();filters={...filters,...Object.fromEntries(new FormData(e.target))};pageNumber=1;render();};
}
function managePipelines(){openDialog('Gerenciar pipelines',`<div class="formbody"><p class="notice">Crie pipelines independentes para leads, oportunidades e pós-venda. Os negócios permanecem vinculados às suas etapas mesmo após renomear ou reordenar.</p><div class="settingslist">${state.pipelines.map(p=>`<div class="settingsrow"><div><h3>${esc(p.name)}</h3><p>${typeNames[p.type]} · ${p.stages.length} etapas · ${state.deals.filter(d=>d.pipelineId===p.id).length} negócios</p></div><div class="actions">${button('Editar','editPipeline',p.id)}${button('Duplicar estrutura','duplicatePipeline',p.id)}</div></div>`).join('')}</div></div><div class="dialogfoot">${button('＋ Novo pipeline','newPipeline','','primary')}${button('Fechar','closeDialog')}</div>`);}
function openPipeline(id,duplicate=false){const original=state.pipelines.find(p=>p.id===id);pipelineDraft=original?structuredClone(original):newPipeline('','opportunity');if(duplicate){pipelineDraft.id=uid();pipelineDraft.name+=' — cópia';pipelineDraft.stages=pipelineDraft.stages.map(s=>({...s,id:uid()}));}const existing=state.pipelines.find(p=>p.id===pipelineDraft.id);
  formDialog(existing?'Configurar pipeline':'Novo pipeline',`<div class="fields">${field('name','Nome do pipeline',pipelineDraft.name,{required:true})}${field('type','Tipo de negócio',pipelineDraft.type,{options:Object.entries(typeNames)})}</div><h3 class="sectiontitle">Etapas do funil</h3><p class="muted">Defina nomes, ordem e probabilidade. Remover uma etapa ocupada exige um destino para seus negócios.</p><div id="stageRows"></div>${button('＋ Adicionar etapa','addStage')}<div id="stageTransfers"></div>`,data=>{syncStages();pipelineDraft.name=data.name.trim();pipelineDraft.type=data.type;const mapping={};document.querySelectorAll('[data-transfer]').forEach(el=>mapping[el.dataset.transfer]=el.value);if(change(s=>configurePipeline(s,structuredClone(pipelineDraft),mapping),'Pipeline salvo.')){pipelineId=pipelineDraft.id;closeDialog();render();}},existing?button('Excluir pipeline','deletePipelineDialog',existing.id,'danger'):'',true);renderStageEditor();}
function syncStages(){document.querySelectorAll('[data-stage-row]').forEach(el=>{const stage=pipelineDraft.stages.find(s=>s.id===el.dataset.stageRow);if(stage){stage.name=el.querySelector('[data-stage-name]').value.trim();stage.probability=Number(el.querySelector('[data-stage-probability]').value);}});}
function renderStageEditor(){const old=state.pipelines.find(p=>p.id===pipelineDraft.id);$('#stageRows').innerHTML=pipelineDraft.stages.map((s,i)=>`<div class="stageedit" data-stage-row="${s.id}"><label>Nome da etapa<input data-stage-name value="${esc(s.name)}" required maxlength="100"></label><label>Chance %<input data-stage-probability type="number" min="0" max="100" step="1" required value="${s.probability}"></label><div class="actions"><button type="button" data-action="stageUp" data-id="${s.id}" aria-label="Subir ${esc(s.name)}" ${i===0?'disabled':''}>↑</button><button type="button" data-action="stageDown" data-id="${s.id}" aria-label="Descer ${esc(s.name)}" ${i===pipelineDraft.stages.length-1?'disabled':''}>↓</button><button type="button" data-action="removeStage" data-id="${s.id}" aria-label="Remover ${esc(s.name)}">×</button></div></div>`).join('');$('#stageTransfers').innerHTML=(old?.stages||[]).filter(s=>!pipelineDraft.stages.some(st=>st.id===s.id)&&state.deals.some(d=>d.pipelineId===old.id&&d.stageId===s.id)).map(s=>`<div class="transferrow"><label>Transferir negócios de “${esc(s.name)}” para<select required data-transfer="${s.id}">${options(pipelineDraft.stages.map(st=>[st.id,st.name]),'','Escolha uma etapa')}</select></label></div>`).join('');}
